const fs = require('node:fs');
const vm = require('node:vm');
const assert = require('node:assert/strict');
console.log('NODE', process.version);
const sources = ['data.js', 'script.js'].map(f => fs.readFileSync(f, 'utf8'));
function harness(failFile) {
  const nodes = {
    'user-select': {value:'', options:[{value:''}], remove(i){this.options.splice(i,1)}, appendChild(o){this.options.push(o)}},
    'user-based-result': {innerHTML:''}, 'item-based-result': {innerHTML:''}
  };
  const requests=[], errors=[];
  const context=vm.createContext({window:{},document:{getElementById:id=>nodes[id],createElement:()=>({})},console:{error:(...args)=>errors.push(args.map(String).join(' '))},fetch:async name=>{requests.push(name);return name===failFile ? new Response('',{status:404}) : new Response(fs.readFileSync(name));}});
  for (let i=0;i<sources.length;i++) vm.runInContext(sources[i],context,{filename:['data.js','script.js'][i]});
  return {context,nodes,requests,errors,run:code=>vm.runInContext(code,context)};
}
(async()=>{
  const h=harness(); await h.context.window.onload();
  const state=h.run('({numUsers,numMovies,ratingCount:ratings.length,ratingMatrix,firstMovie:movies[0],firstRating:ratings[0],decodedTitle:movies.find(m=>m.id===57)?.title})');
  assert.equal(state.numUsers,943); assert.equal(state.numMovies,1682); assert.equal(state.ratingCount,100000); assert.equal(state.ratingMatrix,null);
  assert.deepEqual(h.requests,['u.item','u.data']); assert.equal(h.nodes['user-select'].options.length,944);
  console.log('INITIALIZATION',JSON.stringify({state,fetchOrder:h.requests,options:h.nodes['user-select'].options.length,firstOption:h.nodes['user-select'].options[1],lastOption:h.nodes['user-select'].options.at(-1),userStatus:h.nodes['user-based-result'].innerHTML,itemStatus:h.nodes['item-based-result'].innerHTML,errors:h.errors}));
  assert.equal(h.run('buildRatingMatrix()'),undefined); assert.equal(h.run('ratingMatrix'),null);
  console.log('MATRIX_STUB',{returnValue:'undefined',matrix:h.run('ratingMatrix')});
  const cases=[['identical',[1,2],[1,2]],['nontrivial',[2,5,1,2],[3,4,4,4]],['no_overlap',[5,0],[0,4]],['all_zero',[0,0],[0,0]],['one_overlap',[1],[5]],['empty',[],[]]];
  for(const [name,a,b] of cases){ const result=h.context.cosineSimilarity(a,b); assert.equal(result,0); console.log('COSINE_STUB',JSON.stringify({name,result,finite:Number.isFinite(result),requiredRawCosine:name==='identical'||name==='one_overlap'?1:name==='nontrivial'?38/Math.sqrt(34*57):0})); }
  let calls=0; const original=h.context.cosineSimilarity; h.context.cosineSimilarity=(...args)=>{calls++;return original(...args)};
  let allEmpty=true, deterministic=true;
  for(let u=1;u<=943;u++) for(const fn of ['getUserBasedRecommendations','getItemBasedRecommendations']){
    const first=JSON.stringify(h.context[fn](u)); const second=JSON.stringify(h.context[fn](u));
    allEmpty=allEmpty&&first==='[]';deterministic=deterministic&&first===second;
  }
  assert.ok(allEmpty&&deterministic); assert.equal(calls,0);
  console.log('ALL_EXISTING_USERS',{users:943,methods:2,repetitions:2,allEmpty,deterministic,similarityCalls:calls});
  h.context.getRecommendations(); assert.match(h.nodes['user-based-result'].innerHTML,/Please select a user first/);
  console.log('NO_SELECTION',h.nodes['user-based-result'].innerHTML);
  h.nodes['user-select'].value='1';h.context.getRecommendations();
  assert.match(h.nodes['user-based-result'].innerHTML,/Implement the TODO/);assert.equal(h.nodes['user-based-result'].innerHTML,h.nodes['item-based-result'].innerHTML);
  console.log('SELECT_USER_1',h.nodes['user-based-result'].innerHTML);
  h.context.renderList('user-based-result',[{title:'Audit fixture',score:4.12345}]); assert.match(h.nodes['user-based-result'].innerHTML,/4\.123/);
  console.log('RENDER_FINITE_FIXTURE',h.nodes['user-based-result'].innerHTML);
  h.context.renderList('user-based-result',[{title:'NaN fixture',score:NaN},{title:'Infinity fixture',score:Infinity}]);
  console.log('RENDER_NONFINITE_FIXTURE',h.nodes['user-based-result'].innerHTML);
  assert.match(h.nodes['user-based-result'].innerHTML,/NaN/);assert.match(h.nodes['user-based-result'].innerHTML,/Infinity/);
  h.run('populateUserDropdown()');assert.equal(h.nodes['user-select'].options.length,944);
  console.log('DROPDOWN_REPOPULATE',{options:944});
  await h.run('loadData()');const reload=h.run('({movies:movies.length,ratings:ratings.length,numMovies,numUsers,ratingMatrix})');
  assert.equal(reload.movies,3364); assert.equal(reload.ratings,200000);
  console.log('SECOND_LOAD_IN_SAME_CONTEXT',JSON.stringify(reload));
  for(const file of ['u.item','u.data']){
    const f=harness(file);await f.context.window.onload();
    assert.match(f.nodes['user-based-result'].innerHTML,/Error/);assert.equal(f.nodes['item-based-result'].innerHTML,'<p>Loading movie data...</p>');
    console.log('SIMULATED_FETCH_FAILURE',JSON.stringify({file,fetchOrder:f.requests,user:f.nodes['user-based-result'].innerHTML,item:f.nodes['item-based-result'].innerHTML,errorCount:f.errors.length}));
  }
  console.log('BASELINE_CHARACTERIZATION_ASSERTIONS_PASSED; REQUIRED_CF_BEHAVIOR_REMAINS_UNIMPLEMENTED; NO_BROWSER_USED');
})().catch(e=>{console.error(e);process.exitCode=1});
